<?php use VazinCMS\Security;require __DIR__.'/partials/head.php';?><section class="page-head"><h1>مدیریت منوها</h1><p>پیوندهای هر زبان را جداگانه و به ترتیب دلخواه بسازید.</p></section><?php if($error):?><div class="alert error"><?=Security::e($error)?></div><?php endif;?><section class="grid two"><form class="card" method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>عنوان<input name="label" required></label><label>نشانی<input name="url" dir="ltr" required placeholder="/fa/page/about"></label><label>زبان<select name="locale"><?php foreach(['fa','ar','en','ru','tr','hy','kk','tg','zh'] as $locale):?><option><?=$locale?></option><?php endforeach;?></select></label><label>ترتیب<input type="number" name="position" value="10" min="0"></label><button>افزودن به منو</button></form><div class="card"><h2>پیوندهای منو</h2><?php foreach($items as $item):?><article><?=Security::e($item['locale'].' — '.$item['label'])?> <code><?=Security::e($item['url'])?></code><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="button secondary">حذف</button></form></article><?php endforeach;?><?php if(!$items):?><p>منویی ساخته نشده است.</p><?php endif;?></div></section><?php require __DIR__.'/partials/foot.php';?>
